/* numbers page: number words inside a verse are coloured */
const NUMW = /^(?:[وفبلك]|ال|لل|وال|فال|بال)?(?:واحد|وحد|احد|اثنت|اثن|ثنت|ثلث|ثلاث|اربع|خمس|ست|سبع|ثمني|ثمن|ثمان|تسع|عشر|مائت|مائ|ميه|مايه|الف|الاف|نصف|ربع|سدس|بضع|زوج|شهرين|شهران)(?:ه|ا|ي|ان|ين|ون|ات)?$/;
const hlNum = (t) => t.split(/\s+/).map((w) => {
  const n = w.replace(/[ؐ-ًؚ-ٰٟۖ-ۭـ]/g, '').replace(/[ٱأإآ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه');
  return NUMW.test(n) ? `<span class="nw">${esc(w)}</span>` : esc(w);
}).join(' ');
/* an opened box stays in place (highlighted); its explanation opens as a full-width panel under its row */
function panelize(list, is = (d) => d.classList.contains('lesson')) {
  const place = (d) => {
    const top = d.offsetTop; let last = d;
    for (let n = d.nextElementSibling; n; n = n.nextElementSibling) if (is(n) && n.offsetTop === top) last = n;
    last.after(d._p);
    const col = d.parentNode, wide = col.classList.contains('gcards') && col.closest('.ncols');   // a card in a narrow column: the panel spans all the columns
    if (wide) { const W = wide.getBoundingClientRect(), C = col.getBoundingClientRect(); d._p.style.width = W.width + 'px'; d._p.style.marginRight = (C.right - W.right) + 'px'; }
  };
  list.addEventListener('toggle', (e) => {
    const d = e.target; if (!d.classList || !is(d)) return;
    if (!d._p) { d._p = document.createElement('div'); d._p.className = 'npanel'; [...d.children].slice(1).forEach((c) => d._p.append(c)); }
    if (d.open) place(d); else d._p.remove();
  }, true);
  addEventListener('resize', () => list.querySelectorAll('details[open]').forEach((d) => d._p && is(d) && place(d)));
}
addEventListener('mouseover', (e) => {   // the pairs circle (#stats): pointing at a name shows only its pairs
  const g = e.target.closest?.('.chord g[data-n]'), svg = g?.closest('.chord'), n = g?.dataset.n;
  document.querySelectorAll('.chord').forEach((c) => { const on = c === svg; c.classList.toggle('hl', on); c.querySelectorAll('.rb').forEach((r) => r.classList.toggle('on', on && (r.dataset.a === n || r.dataset.b === n))); c.querySelectorAll('g[data-n]').forEach((x) => x.classList.toggle('on', on && (x === g || [...c.querySelectorAll('.rb.on')].some((r) => r.dataset.a === x.dataset.n || r.dataset.b === x.dataset.n)))); });
});
const PANEL_TOPICS = ['numbers', 'jannah', 'jannah2', 'jesus', 'qiyamah', 'hafiz', 'names', 'places', 'food', 'akhlaq', 'family', 'water', 'falak', 'animals', 'others', 'sifat', 'jews', 'duasp', 'duasb', 'prophets'];      // topic pages whose boxes open as a full-width panel, verses as «سورة … — الآية …: text»
