    const FOOD = ['أنهار الجنة', 'عيون الجنة', 'الفاكهة', 'ثمار متشابهة', 'قطوفها دانية', 'الطعام واللحم', 'الشراب', 'الرحيق المختوم والتسنيم', 'كأس لا لغو فيها'];
